update public.spell_catalog set name_ru='Магический глаз', casting_time='Действие', spell_range='30 футов', area='1 невидимый парящий сенсор', duration='Концентрация, до 1 часа', components=array['В','С','М'], material='кусочек меха летучей мыши', check_type='', damage='', effect_summary='Создаёшь невидимый неуязвимый глаз, через который видишь во все стороны. Он имеет тёмное зрение 30 футов. Бонусным действием можно перемещать глаз до 30 футов в любом направлении.', upcast='', notes='Твёрдые преграды блокируют движение, но глаз проходит через отверстия диаметром от 1 дюйма.', author_description='Волшебник создаёт летающий глаз, потому что идти самому — занятие для людей без высшего магического образования.', author_comment='Если глаз первым увидел причину не заходить в комнату, впервые послушай волшебника.' where slug='arcane-eye';
update public.spell_catalog set name_ru='Аура жизни', casting_time='Действие', spell_range='На себя', area='Эманация радиусом 30 футов', duration='Концентрация, до 10 минут', components=array['В'], material=null, check_type='', damage='Сопротивление некротическому урону; союзник с 0 HP в начале хода восстанавливает 1 HP', effect_summary='Ты и союзники в ауре получаете сопротивление некротическому урону, максимум HP нельзя уменьшить. Союзник с 0 HP, начинающий ход в ауре, восстанавливает 1 HP.', upcast='', notes='Эффект действует только пока существо находится в ауре.', author_description='Жрец или паладин превращает тридцать футов вокруг себя в место, где смерть вынуждена работать сверхурочно.', author_comment='Один HP — немного. Но мёртвому обычно не хватает именно одного.' where slug='aura-of-life';
update public.spell_catalog set name_ru='Изгнание', casting_time='Действие', spell_range='30 футов', area='1 видимое существо', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='пентакль', check_type='Спасбросок Харизмы', damage='', effect_summary='При провале цель переносится в безвредный демиплан и становится Недееспособной. После окончания возвращается в прежнее или ближайшее свободное место.', upcast='+1 цель за каждый уровень ячейки выше 4.', notes='Если цель — Аберрация, Небожитель, Элементаль, Фея или Исчадие и концентрация удержана полную минуту, она не возвращается, а отправляется на связанный с её типом план в случайное место по выбору Мастера.', author_description='На минуту отправляешь существо в отдельную реальность подумать о поведении. Для некоторых монстров минута становится билетом в один конец.', author_comment='Редкое заклинание, где фраза «иди к себе домой» является техническим описанием эффекта.' where slug='banishment';
update public.spell_catalog set name_ru='Чёрные щупальца', casting_time='Действие', spell_range='90 футов', area='Квадрат 20 × 20 футов на земле', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='щупальце', check_type='Спасбросок Силы; освобождение: Сила (Атлетика) против Сл спасброска заклинаний', damage='3к6 дробящего при провале', effect_summary='Область становится труднопроходимой. Существа в ней при появлении, входе или окончании хода делают спасбросок Силы; при провале получают 3к6 и становятся Опутанными до конца заклинания.', upcast='', notes='Одно существо делает спасбросок не чаще одного раза за ход. Опутанная цель может действием попытаться освободиться проверкой Атлетики.', author_description='Двадцать футов чёрных щупалец из земли. Волшебник утверждает, что это контролируемая магия. Земля выглядит менее уверенно.', author_comment='Если кто-то добровольно идёт обратно в щупальца, магия уже не главная проблема.' where slug='black-tentacles';
update public.spell_catalog set name_ru='Увядание', casting_time='Действие', spell_range='30 футов', area='1 видимое существо или немагическое растение', duration='Мгновенно', components=array['В','С'], material=null, check_type='Спасбросок Телосложения; Растения автоматически проваливают', damage='8к8 некротического; половина при успехе', effect_summary='Высасываешь жизненную силу из существа. Растительное существо автоматически проваливает спасбросок. Немагическое растение, не являющееся существом, просто увядает и погибает.', upcast='+1к8 урона за каждый уровень ячейки выше 4.', notes='Для обычного немагического растения спасброска нет.', author_description='Восемь к8 некротикой или мгновенная смерть куста. Друидская ботаника иногда заканчивается подозрительно быстро.', author_comment='Если растение могло бы дать показания, оно назвало бы это преднамеренным преступлением.' where slug='blight';
update public.spell_catalog set name_ru='Очарование монстра', casting_time='Действие', spell_range='30 футов', area='1 видимое существо', duration='1 час', components=array['В','С'], material=null, check_type='Спасбросок Мудрости; с преимуществом, если вы сражаетесь с целью', damage='', effect_summary='При провале цель становится Очарованной и Дружелюбной к тебе на час.', upcast='+1 цель за каждый уровень ячейки выше 4.', notes='Эффект заканчивается, если ты или союзники наносите цели урон. После окончания цель знает, что была очарована тобой.', author_description='Убеждаешь чудовище, что вы друзья. Особенно впечатляет, если минуту назад вы пытались друг друга убить.', author_comment='После окончания оно всё вспомнит. Планируй следующий час с учётом этого маленького социального долга.' where slug='charm-monster';
update public.spell_catalog set name_ru='Принуждение', casting_time='Действие', spell_range='30 футов', area='Выбранные видимые существа', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='Спасбросок Мудрости; повтор после вынужденного движения', damage='', effect_summary='При провале цели становятся Очарованными. Бонусным действием задаёшь горизонтальное направление; на следующем ходу каждая очарованная цель тратит как можно больше движения, идя туда по безопасному пути.', upcast='', notes='После вынужденного движения цель повторяет спасбросок и при успехе освобождается.', author_description='Не приказываешь людям что делать. Просто сообщаешь, в какую сторону им теперь крайне хочется уйти. Бард назовёт это сценическим контролем.', author_comment='Если толпа синхронно уходит от барда, не всегда виновата магия.' where slug='compulsion';
update public.spell_catalog set name_ru='Замешательство', casting_time='Действие', spell_range='90 футов', area='Сфера радиусом 10 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='три скорлупки орехов', check_type='Спасбросок Мудрости; повтор в конце каждого хода', damage='', effect_summary='При провале цель не может использовать Бонусные действия и Реакции и в начале каждого хода бросает 1к10: 1 — движется в случайном направлении без действия; 2–6 — не двигается и не действует; 7–8 — делает одну рукопашную атаку по случайной доступной цели; 9–10 — действует нормально.', upcast='+5 футов к радиусу сферы за каждый уровень ячейки выше 4.', notes='В конце каждого своего хода цель повторяет спасбросок, заканчивая эффект при успехе.', author_description='Превращаешь тактику врага в таблицу случайных решений. У некоторых партий это, впрочем, стандартное состояние без магии.', author_comment='На 9–10 цель ведёт себя нормально. Завидная вероятность для среднего приключенца.' where slug='confusion';
update public.spell_catalog set name_ru='Призыв малых элементалей', casting_time='Действие', spell_range='На себя', area='Эманация радиусом 15 футов', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, check_type='', damage='Каждое твоё попадание по существу в эманации: +2к8 кислотой, холодом, огнём или электричеством', effect_summary='Духи стихий окружают тебя. Каждая твоя атака, попавшая по существу внутри эманации, наносит дополнительно 2к8 выбранного при попадании стихийного урона. Земля в эманации является труднопроходимой для врагов.', upcast='+1к8 дополнительного урона за каждый уровень ячейки выше 4.', notes='Тип урона можно выбирать заново при каждом попадании. Использована актуальная официальная errata 2024.', author_description='Окружаешь себя элементальными духами и заставляешь каждое попадание становиться существенно хуже для получателя. Волшебник наконец нашёл способ сделать чужой меч частью своей магии.', author_comment='Если воин внезапно начал светиться стихиями, просто позволь ему работать.' where slug='conjure-minor-elementals';
update public.spell_catalog set name_ru='Призыв лесных существ', casting_time='Действие', spell_range='На себя', area='Эманация радиусом 10 футов', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, check_type='Спасбросок Мудрости; не чаще 1 раза за ход на существо', damage='5к8 силового; половина при успехе', effect_summary='Природные духи окружают тебя. Когда эманация входит в пространство видимого существа, либо существо входит в неё или заканчивает там ход, можно заставить его сделать спасбросок. Также на время действия можешь Отходить бонусным действием.', upcast='+1к8 урона за каждый уровень ячейки выше 4.', notes='Одно существо делает этот спасбросок не чаще одного раза за ход. Использована актуальная официальная errata 2024.', author_description='Друид окружает себя лесными духами, которые наносят пять к8 всем, кто подходит слишком близко. Очень трогательная связь с природой.', author_comment='Не гладьте друида. На четвёртом круге это уже официально опасная зона.' where slug='conjure-woodland-beings';
update public.spell_catalog set name_ru='Управление водой', casting_time='Действие', spell_range='300 футов', area='Куб до 100 футов по стороне', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='смесь воды и пыли', check_type='Водоворот: спасбросок Силы; освобождение — Сила (Атлетика) против Сл', damage='Водоворот: 2к8 дробящего; половина при успехе', effect_summary='Управляешь водой в кубе до 100 футов и выбираешь один режим: Подъём воды, Разделение воды, Изменение течения или Водоворот. Действием Магии в следующие ходы можно повторять или менять режим.', upcast='', notes='Подъём может дать волну высотой 20 футов и с шансом 25% перевернуть Огромное или меньшее судно. Разделение создаёт траншею. Изменение течения заставляет воду течь даже вверх. Водоворот требует область воды минимум 50×50 футов и 25 футов глубины, тянет существ на 10 футов и затрудняет отплытие.', author_description='Сто футов воды начинают слушаться одного человека. Моря обычно не подписывались на такие отношения.', author_comment='Если волшебник говорит, что «просто немного перенаправит течение», убери лодку подальше.' where slug='control-water';
update public.spell_catalog set name_ru='Оберег от смерти', casting_time='Действие', spell_range='Касание', area='1 существо', duration='8 часов', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Первый раз, когда цель должна упасть до 0 HP, она вместо этого остаётся на 1 HP, после чего заклинание заканчивается. Если пока заклинание действует цель должна мгновенно погибнуть от эффекта без урона, этот эффект отменяется и заклинание заканчивается.', upcast='', notes='Срабатывает только один раз.', author_description='Восемь часов носишь с собой одно официально заверенное «нет» для смерти.', author_comment='Не делает тебя бессмертным. Даёт одну дополнительную ошибку. Приключенцам обычно мало.' where slug='death-ward';
update public.spell_catalog set name_ru='Дверь измерений', casting_time='Действие', spell_range='500 футов', area='Ты и, при желании, 1 добровольное существо рядом', duration='Мгновенно', components=array['В'], material=null, check_type='', damage='При занятой/заполненной точке назначения: 4к6 силового каждому путешественнику, телепортация проваливается', effect_summary='Телепортируешься точно в выбранное место в пределах 500 футов: видимое, представляемое или описанное расстоянием и направлением. Можно взять одно добровольное существо в 5 футах; оно появляется в 5 футах от тебя.', upcast='', notes='Если точка назначения занята существом или полностью заполнена объектами, телепортация проваливается и каждый путешественник получает 4к6 силового урона.', author_description='Пятьсот футов мгновенного побега без необходимости видеть место назначения. Именно поэтому существует отдельный абзац про появление внутри стены.', author_comment='Фраза «я примерно знаю, что там» плохо сочетается с телепортацией.' where slug='dimension-door';
update public.spell_catalog set name_ru='Прорицание', casting_time='Действие', spell_range='На себя', area='На себя', duration='Мгновенно', components=array['В','С','М'], material='ладан стоимостью 25+ зм, расходуется', check_type='', damage='', effect_summary='Задаёшь богу или его служителям один вопрос о конкретной цели, событии или действии, которое должно произойти в ближайшие 7 дней. Получаешь правдивый, но возможно краткий или загадочный ответ.', upcast='', notes='Ритуал. Не учитывает обстоятельства, которые позже изменят результат. После первого применения до долгого отдыха каждое следующее получает накопительный шанс 25% не дать ответа.', author_description='Платишь ладаном, чтобы спросить высшие силы, что будет на неделе. Жрец называет это откровением. Я — дорогим способом получить загадку.', author_comment='Если бог отвечает стихами, он просто не хочет брать ответственность за совет.' where slug='divination';
update public.spell_catalog set name_ru='Подчинение зверя', casting_time='Действие', spell_range='60 футов', area='1 видимый Зверь', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='Спасбросок Мудрости; преимущество, если вы сражаетесь; повтор после каждого получения урона', damage='', effect_summary='При провале Зверь становится Очарованным. Пока вы на одном плане, у тебя есть телепатическая связь: без действия отдаёшь команды, которые он выполняет. Чтобы приказать использовать Реакцию, тратишь собственную Реакцию.', upcast='Ячейка 5: до 10 минут; 6: до 1 часа; 7+: до 8 часов концентрации.', notes='После каждого получения урона цель повторяет спасбросок и при успехе освобождается.', author_description='Берёшь зверя и временно заменяешь его собственные решения своими. Лунные друиды обычно делают наоборот — заменяют свои решения звериными.', author_comment='Если медведь перестал тебя слушаться после первого удара, это не предательство. Это здравый смысл.' where slug='dominate-beast';
update public.spell_catalog set name_ru='Изготовление', casting_time='Действие', spell_range='120 футов', area='Видимые исходные материалы', duration='Мгновенно', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Преобразуешь сырьё в готовый предмет из того же материала. Обычно можно создать Большой или меньший предмет в кубе 10 футов или восьми соединённых кубах 5 футов; из металла, камня и минералов — не больше Среднего размера в кубе 5 футов.', upcast='', notes='Нельзя создавать существ и магические предметы. Для оружия, брони и других изделий высокой сложности нужна владение соответствующими инструментами ремесленника. Качество изделия зависит от сырья.', author_description='Волшебник наконец применяет магию не чтобы уничтожить вещь, а чтобы её сделать. Почти взросление.', author_comment='Да, можно изготовить мост. Нет, отсутствие инженерных навыков от этого не становится достоинством.' where slug='fabricate';
update public.spell_catalog set name_ru='Верный пёс', casting_time='Действие', spell_range='30 футов', area='1 свободное место; охрана в радиусе 30 футов', duration='8 часов', components=array['В','С','М'], material='серебряный свисток', check_type='Враг в 5 футах в начале твоего хода: спасбросок Ловкости', damage='4к8 силового при провале', effect_summary='Призываешь невидимого для всех кроме тебя неосязаемого неуязвимого сторожевого пса. Существо Маленького размера или больше, подошедшее в 30 футов без пароля, вызывает громкий лай. Пёс имеет истинное зрение 30 футов. В начале твоего хода пытается укусить врага в 5 футах.', upcast='', notes='Исчезает, если расстояние между вами больше 300 футов. Действием Магии можно перемещать его до 30 футов.', author_description='Невидимый пёс, который не ест, не спит, видит истину и кусает силовым уроном. Наконец домашнее животное для волшебника.', author_comment='Пароль лучше не сообщать плуту. Он забудет его ровно после того, как украдёт свисток.' where slug='faithful-hound';